switch param(0, 0) {
case 0:
	p.screen.ClearLine()
	cur := p.screen.CurrentCursor()
	for r := cur.Row + 1; r < p.screen.Rows; r++ {
		for c := 0; c < p.screen.Cols; c++ {
			p.screen.Cells[r][c] = Cell{}
		}
	}
case 1:
	cur := p.screen.CurrentCursor()
	for r := 0; r < cur.Row; r++ {
		for c := 0; c < p.screen.Cols; c++ {
			p.screen.Cells[r][c] = Cell{}
		}
	}
	for c := 0; c <= cur.Col; c++ {
